function chooseTask(){let f2Possible=S.cond.morning==='fog'||['rain','wind'].includes(S.cond.afternoon),fergusTalkTime=S.cond.event==='fair'?16:10,legacy=['morag','hamish','fergus'],canRaise=id=>{let base=S.moods[id],bonus=id==='morag'?15:id==='hamish'?15+(f2Possible?10:0)-(S.cond.morning==='fog'?15:0):id==='fergus'?10+(fergusTalkTime<17?5:0)+(f2Possible?10:0):15;return base+bonus>=66};let eligible=taskPool.filter(t=>{if(t.eligible&&!t.eligible(S))return false;if(t.id==='pub-visit')return S.cond.morning==='fog'||['rain','wind'].includes(S.cond.afternoon);if(t.id==='outdoor-tables')return S.cond.afternoon!=='rain';if(t.id==='morning-catch')return S.cond.morning!=='fog';if(t.id==='good-day')return legacy.every(canRaise);if(t.id==='honest-forecast')return legacy.filter(canRaise).length>=2;return true});let fresh=eligible.filter(t=>!S.completedTasks.includes(t.id));return pick(fresh.length?fresh:eligible)}
