for(const story of stories)story.resolved=!!saved.stories?.[story.id]?.resolved||(story.id==='bribed-referee'&&!!saved.refereeFair);
function storyResolved(id){if(id==='old-friends')return conflictResolved('old-friends');return !!stories.find(s=>s.id===id)?.resolved}
