const point=z=>locations[z]||locations.pub, dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y), pick=a=>a[Math.floor(Math.random()*a.length)];
function save(){localStorage.setItem('dreich-day-save',JSON.stringify({loop:S.loop,journal:S.journal,observations:S.observations,completedTasks:S.completedTasks,appearedTasks:S.appearedTasks,taskHints:S.taskHints,conflicts:Object.fromEntries(conflicts.map(c=>[c.id,{resolved:c.resolved}])),stories:Object.fromEntries(stories.map(s=>[s.id,{resolved:s.resolved}])),storySeen:S.storySeen,conflictSeen:S.conflictSeen,refereeFair:S.refereeFair,bestResult:S.bestResult,matchesPlayed:S.matchesPlayed,gameCompleted:S.gameCompleted,hintsSeen:S.hintsSeen}));hasSave=true}
function markStoryStep(id,step){S.storySeen[id]??=[];if(!S.storySeen[id].includes(step)){S.storySeen[id].push(step);S.storySeen[id].sort((a,b)=>a-b);save()}}
function markConflictStep(id,step){S.conflictSeen[id]??=[];if(!S.conflictSeen[id].includes(step)){S.conflictSeen[id].push(step);S.conflictSeen[id].sort((a,b)=>a-b);save()}}
function resolveConflict(id){let conflict=conflicts.find(c=>c.id===id);if(conflict&&!conflict.resolved){conflict.resolved=true;save()}}
function storyProgress(id='old-friends'){return S.storyProgress[id]||(S.storyProgress[id]={step:0,agreed:false,sceneStarted:false})}
function roll(){let morning=pick(['sun','rain','fog','wind']),afternoon=Math.random()<.5?morning:pick(['sun','rain','fog','wind'].filter(w=>w!==morning)),expected={sun:'emerged',rain:'stayed',fog:'peeked'}[afternoon],sign=afternoon==='wind'?pick(['emerged','stayed']):Math.random()<.7?expected:pick(['emerged','stayed','peeked'].filter(x=>x!==expected));return{morning,afternoon,sign,event:(()=>{let r=Math.random();return r<.25?'fair':r<.5?'angus':r<.75&&!storyResolved('bribed-referee')?'rupert':'none'})(),moods:Object.fromEntries(npcs.map(n=>[n.id,Math.floor(Math.random()*31)+40]))}}
function begin(){S.time=6;S.elapsed=0;S.finalGathered=false;S.finalArrivals=[];S.finalHandled=false;S.finalScore=null;S.finalStoryResolved=false;S.matchMode=false;S.match=null;S.cond=roll();S.forecast=null;S.moods={...S.cond.moods};let oldConflict=conflicts.find(c=>c.id==='old-friends');if(oldConflict&&!oldConflict.resolved)for(const id of [oldConflict.a,oldConflict.b])if(S.moods[id]!=null)S.moods[id]=Math.min(60,S.moods[id]);angus.mood=50;S.rabPlayedHours.clear();S.rabWindDay=false;resetSheep();S.storyProgress={'old-friends':{step:0,agreed:false,sceneStarted:false},'bribed-referee':{scoopAccepted:false},'fish-buns':{hamishAgreed:false},'psalms-pipes':{iainAgreed:false}};S.receiptAvailable=false;S.receiptHeld=false;S.receiptSpawned=false;S.b1Happened=false;S.bridieTargetId=null;S.talked.clear();S.applied.clear();S.seen.clear();S.weatherDone=false;S.ritual=false;S.player={x:8.5,y:9};S.taskDone=false;S.taskLeftPier=false;S.iainCompanionId=null;angus.x=16;angus.y=29.4;angus.gone=false;rupert.x=20.5;rupert.y=17.5;rupert.visible=false;rupert.routeKey=null;rupert.route=[];rupert.routeIndex=0;angus.routeKey=null;angus.route=[];angus.routeIndex=0;S.task=chooseTask();if(S.task&&!S.appearedTasks.includes(S.task.id)){S.appearedTasks.push(S.task.id);save()}S.active=true;ui.title.classList.add('hidden');ui.layer.classList.add('hidden');ui.hud.classList.remove('hidden');toast('Петля '+S.loop+' · новый день в Глен-Дрихе',2600);renderTask();showNewspaper();save()}
function returnToTitle(){S.endingActive=false;ui.layer.classList.add('hidden');ui.layer.innerHTML='';ui.hud.classList.add('hidden');ui.title.classList.remove('hidden');S.active=false;renderTitleMenu()}
function renderTitleMenu(){let box=document.querySelector('#menu-actions');box.innerHTML=(hasSave?'<button id="continue-game">Продолжить</button>':'')+'<button id="new-game">Новая игра</button><button id="how-play">Как играть</button>';let c=document.querySelector('#continue-game');if(c)c.onclick=()=>{if(S.gameCompleted)showCredits();else begin()};document.querySelector('#new-game').onclick=hasSave?askNewGame:begin;document.querySelector('#how-play').onclick=showHowTo}
function askNewGame(){open('<h2>Начать заново?</h2><p>Дневник будет стёрт.</p><button id="new-confirm">Начать заново</button> <button class="plain-button" id="new-cancel">Назад</button>');document.querySelector('#new-confirm').onclick=()=>{localStorage.removeItem('dreich-day-save');location.reload()};document.querySelector('#new-cancel').onclick=returnToTitle}
function showHowTo(){open('<h2>Как играть</h2><p>Цель — выиграть финал по шинти в 16:00 и спасти паб. Каждый день повторяется. Следи за жителями и читай дневник (J): там открываются их скрытые правила. Напиши прогноз в редакции газеты до 9:00. Поднимай настроение, разрешай конфликты и разоблачи подкупленного судью.</p><p>WASD / стрелки — ходить; E — говорить; J — дневник; M — звук.</p><button id="how-close">Закрыть</button>');document.querySelector('#how-close').onclick=returnToTitle}
renderTitleMenu();
function taskStatus(){return !S.task?'нет задания':S.taskDone?(S.task.status==='completed'?'выполнено':'провалено'):'в процессе'}
function renderTask(){let el=document.querySelector('#task-card');if(!S.task){el.classList.add('hidden');return}el.innerHTML='<strong>'+S.task.requester+' · '+S.task.text+'</strong><span>Цель: '+S.task.goal+'</span><small>До '+taskDeadline(S.task.deadline)+' · '+taskStatus()+'</small>';el.classList.remove('hidden')}
function showNewspaper(){if(!S.task&&!S.refereeFair)return;open('<p class="eyebrow">ГЛЕН-ДРИХ · УТРЕННИЙ ВЫПУСК</p>'+(S.refereeFair?'<h2>СКУННЕРСБИ ПОДКУПИЛ СУДЬЮ</h2>':'<h2>Объявления</h2>')+(S.task?'<div class="task-ad"><strong>'+S.task.requester+' · '+S.task.text+'</strong><p>Нужно: '+S.task.hint+'</p><small>Срок: до '+taskDeadline(S.task.deadline)+' · в процессе</small></div>':'')+'<button id="newspaper-close">Закрыть газету</button>');document.querySelector('#newspaper-close').onclick=close}
function inPub(n){return n.x>5.35&&n.x<9.65&&n.y>6.15&&n.y<9.85}
function completeTask(){if(S.taskDone)return;S.taskDone=true;S.task.status='completed';if(S.task.npc)mood(S.task.npc,15);if(!S.completedTasks.includes(S.task.id)){S.completedTasks.push(S.task.id);let loops=S.journal,rule=rules.find(r=>(loops[r.id]?.loops||[]).length<2&&!S.taskHints[r.id]);if(rule){let clues={M1:'Мораг не всегда ночует под своей крышей.',M2:'Мораг как-то связана с ясным небом.',H1:'Прогноз способен оторвать Хэмиша от пирса.',H2:'Туман меняет планы Хэмиша.',F1:'Ярмарка притягивает хозяина паба.',F2:'Хороший разговор у стойки поднимает настроение.',D1:'Приезд Ангуса запирает Дуги дома.',D2:'Солнце возвращает капитана на тренировку.',D3:'После примирения Дуги тренируется вместе с Ангусом.',E1:'Ошибочный прогноз заставляет Элспет писать поправку.',E2:'На ярмарке Элспет выходит за новостями.',I1:'Туман приводит жителей к звону колокола.',I2:'Иэн замечает тех, кому тяжелее всех.'};S.taskHints[rule.id]=clues[rule.id]}}save();renderTask();toast('Задание выполнено!',3000)}
function failTask(){if(S.taskDone)return;S.taskDone=true;S.task.status='failed';if(S.task.npc)mood(S.task.npc,-5);renderTask();toast('Задание провалено',3000)}
function checkTask(){if(!S.task||S.taskDone)return;let hamish=npcs.find(n=>n.id==='hamish'),legacy=['morag','hamish','fergus'],success=false;if(S.task.id==='pub-visit'&&S.time<12&&inPub(hamish))success=true;if(S.task.id==='outdoor-tables'&&S.time>=12.5)success=S.forecast==='sun'&&S.cond.afternoon!=='rain';if(S.task.id==='morning-catch'){if(S.time<12&&npcLoc('hamish')!=='pier')S.taskLeftPier=true;if(S.time>=12)success=!S.taskLeftPier}if(S.task.id==='good-day'&&S.time<17)success=legacy.every(id=>S.moods[id]>=66);if(S.task.id==='honest-forecast'&&S.time>=17)success=S.forecast===S.cond.afternoon&&legacy.filter(id=>S.moods[id]>=66).length>=2;if(S.task.id==='shinty-training'&&S.time>=12)success=npcLoc('dougie')==='green'&&dist(npcs.find(n=>n.id==='dougie'),locations.green)<1.5;if(S.task.id==='clean-issue'&&S.time>=16)success=S.forecast===S.cond.afternoon&&S.moods.elspeth>=66;if(S.task.id==='full-kirk'&&S.time>=9)success=kirkAttendees.every(id=>npcLoc(id)==='kirk');if(S.task.id==='rab-pipes'&&S.time>=11)success=rabPlaying();if(S.task.id==='sheep-fair'&&S.time>=12)success=npcLoc('kenny')==='square'&&sheepFlock.slice(0,2).every(s=>dist(s,locations.square)<3);if(success){completeTask();return}if(S.time>=S.task.deadline)failTask()}

function baseLoc(n,t){return n.base.find(a=>t>=a[0]&&t<a[1])?.[2]||'pub'}
function npcLoc(id){let n=npcs.find(x=>x.id===id);if(!n)return'pub';if(S.finalGathered&&S.time>=15.5&&S.time<16.04&&S.finalArrivals.includes(id))return'green';let loc=baseLoc(n,S.time);for(const r of rules)if(r.npc===id&&r.when(S)&&r.effect.loc&&S.time>=r.effect.from&&S.time<r.effect.to)loc=r.effect.loc;if(S.time>=6&&S.time<7.5&&ritualSpots[id])return'ritual';if(id==='rab'&&S.rabWindDay&&S.time>=6&&S.time<18&&!(conflictResolved('psalms-pipes')&&S.time>=15&&S.time<15.5))loc='pub';if(id==='rab'&&!conflictResolved('psalms-pipes')&&S.time>=12&&S.time<13&&S.moods.rab>=66&&currentWeather()!=='wind'&&!S.rabWindDay)loc='square';if(id==='rab'&&S.time>=11&&S.time<11.04&&S.moods.rab>=66&&!S.rabWindDay&&currentWeather()!=='wind')loc='square';if(id==='bridie'&&S.bridieTargetId&&S.time>=12&&S.time<13)loc='support';if(id==='kenny'&&S.forecast==='rain'&&S.time>=15&&S.time<18)loc='pub';if(id==='rory'&&rules.some(r=>r.id==='Ro1'&&r.when(S))&&S.time>=13&&S.time<17)loc='tour';if(id==='dougie'&&S.cond?.event==='angus'&&!conflictResolved('old-friends')&&storyProgress().agreed&&S.time>=13&&S.time<15)loc='pub';for(const r of rules){if(r.id==='I1'&&r.when(S)&&r.effect.attendance?.includes(id)&&S.time>=(r.effect.approachFrom??r.effect.from)&&S.time<r.effect.to)loc='kirk'}return loc}

function npcBaseGoal(n){if(S.finalGathered&&S.time>=15.5&&S.time<16.04&&S.finalArrivals.includes(n.id)){let i=S.finalArrivals.indexOf(n.id);return{x:locations.green.x+((i%4)-1.5)*.48,y:locations.green.y+Math.floor(i/4)*.46}}if(n.id==='bridie'&&S.bridieTargetId&&S.time>=12&&S.time<13){let friend=npcs.find(o=>o.id===S.bridieTargetId);if(friend)return{x:friend.x+.8,y:friend.y}}if(S.time>=6&&S.time<7.5&&ritualSpots[n.id])return ritualSpots[n.id];if(n.id==='rory'&&S.time>=13&&S.time<17&&S.cond.afternoon==='sun'&&S.forecast!=='rain')return point(Math.floor(S.time-13)%2===0?'green':'pier');if(n.id==='iain'&&S.iainCompanionId&&S.time>=12&&S.time<12+2/3){let friend=npcs.find(o=>o.id===S.iainCompanionId);if(friend)return{x:friend.x+1,y:friend.y}}return point(npcLoc(n.id))}

function sameNpcTile(a,b){return Math.floor(a.x)===Math.floor(b.x)&&Math.floor(a.y)===Math.floor(b.y)}
function freeNpcGoal(n,anchor,reserved){let cx=Math.floor(anchor.x),cy=Math.floor(anchor.y);for(let radius=0;radius<20;radius++){let candidates=[];for(let dy=-radius;dy<=radius;dy++)for(let dx=-radius;dx<=radius;dx++){if(Math.max(Math.abs(dx),Math.abs(dy))!==radius)continue;let p={x:cx+dx+.5,y:cy+dy+.5};if(walkable(p.x,p.y,'npc')&&!reserved.some(o=>sameNpcTile(o,p))&&!npcs.some(o=>o!==n&&sameNpcTile(o,p)))candidates.push(p)}if(candidates.length)return candidates.sort((a,b)=>dist(a,anchor)-dist(b,anchor))[0]}return anchor}
function faceActor(actor,dx,dy){actor.facing=Math.abs(dx)>Math.abs(dy)?(dx<0?1:2):(dy<0?3:0)}
function moveNPCs(dt){let reserved=[];for(const n of npcs){n.moving=false;let goal=freeNpcGoal(n,npcBaseGoal(n),reserved);reserved.push(goal);let key=goal.x+','+goal.y;if(n.routeKey!==key){n.routeKey=key;n.route=findGridPath(n,goal,'npc');n.routeIndex=0}let left=dt*(S.finalGathered&&S.finalArrivals.includes(n.id)?3.5:.72);while(left>0&&n.routeIndex<n.route.length){let p=n.route[n.routeIndex],dx=p.x-n.x,dy=p.y-n.y,d=Math.hypot(dx,dy);if(d<.015){n.x=p.x;n.y=p.y;n.routeIndex++;continue}let step=Math.min(left,d);faceActor(n,dx,dy);n.moving=true;n.x+=dx/d*step;n.y+=dy/d*step;left-=step;if(step===d)n.routeIndex++}n.animTime=n.moving?(n.animTime||0)+dt:0}}
function sheepFollowing(){return S.cond?.event==='fair'&&S.time>=10&&S.time<14&&npcLoc('kenny')==='square'}
function moveRupert(dt){rupert.moving=false;rupert.visible=S.cond?.event==='rupert'&&!storyResolved('bribed-referee')&&S.time>=9;if(!rupert.visible)return;let goal=S.time<11?locations.pubFront:S.time<13?locations.square:S.time<15?locations.gazetteFront:S.time<16?locations.pubFront:locations.southRoad,key=goal.x+','+goal.y;if(rupert.routeKey!==key){rupert.routeKey=key;rupert.route=findGridPath(rupert,goal,'npc');rupert.routeIndex=0}let left=dt*.72;while(left>0&&rupert.routeIndex<rupert.route.length){let p=rupert.route[rupert.routeIndex],dx=p.x-rupert.x,dy=p.y-rupert.y,d=Math.hypot(dx,dy);if(d<.015){rupert.x=p.x;rupert.y=p.y;rupert.routeIndex++;continue}let step=Math.min(left,d);faceActor(rupert,dx,dy);rupert.moving=true;rupert.x+=dx/d*step;rupert.y+=dy/d*step;left-=step;if(step===d)rupert.routeIndex++}rupert.animTime=rupert.moving?(rupert.animTime||0)+dt:0;if(S.time>=16&&dist(rupert,locations.southRoad)<.6)rupert.visible=false}
function updateSheep(dt){if(!S.cond)return;let follow=sheepFollowing(),kenny=npcs.find(n=>n.id==='kenny');for(const s of sheepFlock){if(follow&&s.id<2){s.targetX=kenny.x+(s.id===0?-.7:.7);s.targetY=kenny.y+.75}else if(s.x<31.4||s.x>38.6||s.y<1.4||s.y>7.6){s.targetX=35+(s.id%2?-.4:.4);s.targetY=7.2}else if(Math.hypot(s.targetX-s.x,s.targetY-s.y)<.2){s.targetX=31.7+sceneRandom()*6.6;s.targetY=1.7+sceneRandom()*5.8}let dx=s.targetX-s.x,dy=s.targetY-s.y,d=Math.hypot(dx,dy),speed=follow&&s.id<2?.42:.13;s.moving=d>.06;if(s.moving){let step=Math.min(d,dt*speed);s.dir=dx<-.01?-1:dx>.01?1:s.dir;s.x+=dx/d*step;s.y+=dy/d*step;s.animTime+=dt}else s.animTime=0;s.x=Math.max(31.25,Math.min(38.75,s.x));s.y=Math.max(1.25,Math.min(7.75,s.y))}}
function checkRupertStory(){if(S.cond?.event==='rupert'&&!storyResolved('bribed-referee')){if(S.time>=11&&S.time<13&&rupert.visible&&dist(rupert,locations.square)<1.6&&dist(S.player,rupert)<=3&&!(S.storySeen['bribed-referee']||[]).includes(1)){markStoryStep('bribed-referee',1);queueNotice('Руперт: «Да, судья в курсе. Конверт после матча.»',3200);queueNotice('История: Подкупленный судья · услышан разговор',3000)}if(S.time>=15&&!S.receiptSpawned){S.receiptSpawned=true;S.receiptAvailable=true}}let p=storyProgress('bribed-referee');if(p.scoopAccepted&&S.time>=17&&!storyResolved('bribed-referee')){let story=stories.find(s=>s.id==='bribed-referee');story.resolved=true;S.refereeFair=true;markStoryStep('bribed-referee',3);rupert.visible=false;toast('Экстренный выпуск: СКУННЕРСБИ ПОДКУПИЛ СУДЬЮ',5000)}}
function pickUpReceipt(){if(!S.receiptAvailable||S.receiptHeld)return;S.receiptAvailable=false;S.receiptHeld=true;markStoryStep('bribed-referee',2);toast('Квитанция: «Силлерберн — судье, £500». Подпись: Р. С.',4600)}
function drawReceipt(){let x=Math.round(S.receiptSpot.x*16),y=Math.round(S.receiptSpot.y*16);rect(x-3,y-2,7,4,'#EFE9D9');rect(x-2,y-1,4,1,P.ink);rect(x+2,y,1,1,P.stone)}
function rabKirkPlaying(){return conflictResolved('psalms-pipes')&&S.time>=15&&S.time<15.5&&npcLoc('rab')==='kirk'&&dist(npcs.find(n=>n.id==='rab'),locations.kirk)<1.6}
function drawSheep(s){let image=sprites.sheep;if(!image?.complete||!image.naturalWidth)return;ctx.save();ctx.translate(Math.round(s.x*16),Math.round(s.y*16));if(s.dir<0)ctx.scale(-1,1);ctx.drawImage(image,-8,-12);ctx.restore()}
function drawPastureFence(){const dark='#3B3029',wood='#79583A';function h(x0,x1,y){for(let x=x0;x<x1;x++){let px=x*16,py=y*16;rect(px,py+4,16,2,dark);rect(px,py+10,16,2,wood);rect(px,py,3,16,dark)}}function v(x,y0,y1){for(let y=y0;y<y1;y++){let px=x*16,py=y*16;rect(px+4,py,2,16,dark);rect(px+10,py,2,16,wood);rect(px,py,16,3,dark)}}h(31,39,1);v(31,1,8);v(39,1,8);h(31,34,8);h(36,39,8);rect(34*16,8*16+3,3,13,dark);rect(36*16-3,8*16+3,3,13,dark);for(let i=3;i<27;i+=4)rect(34*16+i,8*16+4+i/4,3,2,wood)}
function moveAngus(dt){angus.moving=false;angus.visible=!!(S.cond?.event==='angus'&&S.time>=10&&!angus.gone);if(!angus.visible)return;let goal=S.time<13?locations.green:S.time<15?{x:8,y:9.5}:{x:16,y:29.4};let key=goal.x+','+goal.y;if(angus.routeKey!==key){angus.routeKey=key;angus.route=findGridPath(angus,goal,'npc');angus.routeIndex=0}let left=dt*.72;while(left>0&&angus.routeIndex<angus.route.length){let p=angus.route[angus.routeIndex],dx=p.x-angus.x,dy=p.y-angus.y,d=Math.hypot(dx,dy);if(d<.015){angus.x=p.x;angus.y=p.y;angus.routeIndex++;continue}let step=Math.min(left,d);faceActor(angus,dx,dy);angus.moving=true;angus.x+=dx/d*step;angus.y+=dy/d*step;left-=step;if(step===d)angus.routeIndex++}angus.animTime=angus.moving?(angus.animTime||0)+dt:0;if(S.time>=15&&dist(angus,goal)<.45){angus.gone=true;angus.visible=false}}
function currentWeather(){return S.time<12?S.cond.morning:S.cond.afternoon}
function rabPlaying(){let n=npcs.find(x=>x.id==='rab');return !!n&&S.moods.rab>=66&&!S.rabWindDay&&currentWeather()!=='wind'&&npcLoc('rab')==='square'&&dist(n,locations.square)<1.5}
function mood(id,d){let current=id==='angus'?(angus.mood??50):(S.moods[id]??0),cap=conflicts.some(c=>!c.resolved&&(c.a===id||c.b===id))?60:100,value=Math.max(0,Math.min(cap,current+d));if(id==='angus')angus.mood=value;else S.moods[id]=value}
function applyConflictEffects(){let morag=npcs.find(n=>n.id==='morag'),hamish=npcs.find(n=>n.id==='hamish');if(!conflictResolved('fish-buns')&&dist(morag,hamish)<=4&&!S.applied.has('fish-buns:'+S.loop)){S.applied.add('fish-buns:'+S.loop);mood('morag',-5);mood('hamish',-5)}if(conflictResolved('fish-buns')&&!S.applied.has('fish-buns-resolved:'+S.loop)){let together=['square','bakery'].some(place=>npcLoc('morag')===place&&npcLoc('hamish')===place&&npcAtPlace(morag,place)&&npcAtPlace(hamish,place));if(together){S.applied.add('fish-buns-resolved:'+S.loop);mood('morag',5);mood('hamish',5)}}if(!conflictResolved('psalms-pipes')&&S.time>=12&&S.time<13&&rabPlaying()&&!S.applied.has('psalms-pipes:'+S.loop)){S.applied.add('psalms-pipes:'+S.loop);mood('iain',-10)}}
function applyRules(){for(const r of rules){if(!r.when(S))continue;let key=r.id+':'+S.loop;if(r.id==='R1'&&rabPlaying()){let hour=Math.floor(S.time);if(!S.rabPlayedHours.has(hour)){S.rabPlayedHours.add(hour);let rab=npcs.find(n=>n.id==='rab');for(const n of npcs)if(dist(n,rab)<=5)mood(n.id,5)}}if(r.id==='Ma2'&&rabPlaying()&&!S.applied.has(key)){S.applied.add(key);mood('malcolm',10);toast('Малкольм отбивает ритм в кузнице. Настроение +10.',2600)}if(r.effect.at!=null&&S.time>=r.effect.at&&!S.applied.has(key)){S.applied.add(key);if(r.id==='M2'){if(S.cond.afternoon==='rain')mood('morag',-20);else toast('Мораг выставила столики у пекарни.',2200)}if(r.effect.mood)mood(r.npc,r.effect.mood);if(r.id==='R2')S.rabWindDay=true;if(r.id==='B1')S.b1Happened=true;if(r.id==='B2'&&!S.bridieTargetId){let target=npcs.filter(n=>n.id!=='bridie'&&S.moods[n.id]<30).sort((a,b)=>S.moods[a.id]-S.moods[b.id])[0];if(target){S.bridieTargetId=target.id;mood(target.id,10);mood('bridie',-5);toast('Бриди пошла к '+target.name+'. Настроение: '+target.name+' +10, Бриди −5.',3600)}}if(r.id==='P1'){mood('iain',10);mood('bridie',10);toast('Рэб играет у дверей кирка. Иэн и Бриди +10.',3200)}if(r.id==='D3')mood('angus',10);if(r.id==='H2')mood('hamish',-15);if(r.id==='I1'){toast('Звонит колокол кирка');for(const id of r.effect.attendance)mood(id,5)}if(r.id==='I2'){let saddest=npcs.filter(n=>n.id!=='iain'&&S.moods[n.id]<34).sort((a,b)=>S.moods[a.id]-S.moods[b.id])[0];if(saddest){S.iainCompanionId=saddest.id;mood(saddest.id,15)}}if(r.id==='B1'){for(const n of npcs)mood(n.id,5);toast('Бриди: доброе знамение! Настроение жителей +5.',3200)}}if(r.id==='F2'&&r.when(S)&&!S.applied.has(key)){S.applied.add(key);mood('hamish',10);mood('fergus',10);toast('Хэмиш и Фергус беседуют у стойки. Настроение обоих +10.',2600)}}}

function activeRule(r){if(!r.when(S))return false;if(r.id==='R1'||r.id==='Ma2')return rabPlaying();if(r.id==='Ro1')return S.time>=13&&S.time<17;if(r.id==='B2')return S.time>=12&&S.time<13&&S.bridieTargetId!==null;if(r.id==='F-R')return S.time>=9&&S.time<9.08;if(r.id==='F2')return dist(npcs.find(n=>n.id==='hamish'),locations.pub)<1;if(r.id==='I2')return S.time>=12&&S.time<12+(r.effect.duration||.08);if(r.effect.loc)return S.time>=r.effect.from&&S.time<r.effect.to;if(r.effect.at!=null)return S.time>=r.effect.at&&S.time<r.effect.at+.08;return r.effect.from!=null&&S.time>=r.effect.from&&S.time<r.effect.to}
function npcAtPlace(n,place){if(place==='pub')return inPub(n);if(place==='home'){let b=buildings.find(x=>x.id==='home');return n.x>b.x+.3&&n.x<b.x+b.w-.3&&n.y>b.y+1.15&&n.y<b.y+b.h-.15}return dist(n,point(place))<1.35}
function ruleAtDestination(r,n){if(r.effect.loc)return npcLoc(n.id)===r.effect.loc&&npcAtPlace(n,r.effect.loc);if(r.id==='M2')return npcLoc(n.id)==='bakery'&&npcAtPlace(n,'bakery');if(r.id==='Ma2')return npcAtPlace(n,'smithy')&&rabPlaying();if(r.id==='R1')return npcAtPlace(n,'square')&&rabPlaying();if(r.id==='B2'){let friend=npcs.find(o=>o.id===S.bridieTargetId);return !!friend&&dist(n,friend)<1.5}if(r.id==='Ro1')return segdist([n.x,n.y],[locations.green.x,locations.green.y],[locations.pier.x,locations.pier.y])<1.5;if(r.id==='F2')return npcAtPlace(n,'pub')&&npcAtPlace(npcs.find(o=>o.id==='hamish'),'pub');if(r.id==='I1')return npcAtPlace(n,'kirk');if(r.id==='I2'){let friend=npcs.find(o=>o.id===S.iainCompanionId);return !!friend&&dist(n,friend)<1.5}return true}
function observationText(rule){return{M1:'дома вместо пекарни',M2:'выставила столики у пекарни',H1:'пропустил рыбалку и отправился в паб',H2:'ушёл в паб из-за утреннего тумана',H3:'ушёл в лодочную каюту из-за ветра',F1:'торгует на площади',F2:'беседует с Хэмишем в пабе',D1:'закрылся в хижине из-за Ангуса',D2:'тренируется на зелёном поле',E1:'пишет поправку в редакции',E2:'репортирует с ярмарки',I1:'звонит в колокол и собирает жителей',I2:'поддерживает самого печального жителя','F-R':'снова меряет паб рулеткой для Руперта',B2:'пошла к самому печальному жителю',P1:'играет у дверей кирка',R1:'играет на волынке на площади',R2:'отказался играть из-за ветра и ушёл в паб',K1:'держит стадо на пастбище из-за дождя',K2:'привёл овец на ярмарку',Ma1:'ушёл в паб из-за тумана у кузницы',Ma2:'отбивает ритм молотом под волынку',Ro1:'водит туристов вдоль берега',Ro2:'отдыхает в домике из-за дождя',B1:'объявила доброе знамение'}[rule.id]||'изменил планы'}

function discover(){for(const n of npcs)if(dist(S.player,n)<6)for(const r of rules)if(r.npc===n.id&&activeRule(r)&&ruleAtDestination(r,n)){S.journal[r.id]??={loops:[]};if(!S.journal[r.id].loops.includes(S.loop)){let before=S.journal[r.id].loops.length;S.journal[r.id].loops.push(S.loop);let text='Петля '+S.loop+', '+clock()+', '+weather[S.time<12?S.cond.morning:S.cond.afternoon][0]+' — '+n.name+' '+observationText(r);S.observations.unshift(text);S.observations=S.observations.slice(0,15);S.seen.add(r.id);save();queueNotice('Новое наблюдение: '+text+' ('+Math.min(2,before+1)+'/2)',3000);if(before===1)queueNotice('Правило открыто!',3500,true)}else S.seen.add(r.id)}}
function toast(text,ms=2400,large=false){ui.toast.textContent=text;ui.toast.classList.toggle('large',large);ui.toast.classList.remove('hidden');S.toastUntil=performance.now()+ms}
function queueNotice(text,ms,large=false,onDone=null){S.noticeQueue.push({text,ms,large,onDone});if(S.noticeBusy)return;let next=()=>{let item=S.noticeQueue.shift();if(!item){S.noticeBusy=false;return}S.noticeBusy=true;toast(item.text,item.ms,item.large);setTimeout(()=>{if(item.onDone)item.onDone();next()},item.ms)};next()}
function open(html){ui.layer.innerHTML='<div class="panel">'+html+'</div>';ui.layer.classList.remove('hidden');S.active=false}
function close(){ui.layer.classList.add('hidden');ui.layer.innerHTML='';S.active=true}
function forecast(){if(S.time>=9){S.forecast='none';toast('Прогноз уже нельзя изменить.');return}open('<h2>Прогноз на сегодня</h2><p>Какая погода будет после полудня?</p><div class="weather-options">'+[['sun','Солнце'],['rain','Дождь'],['fog','Туман'],['wind','Ветер']].map(a=>'<button data-w="'+a[0]+'">'+a[1]+'</button>').join('')+'</div><button class="plain-button" data-close>Закрыть · Esc</button>');ui.layer.querySelectorAll('[data-w]').forEach(b=>b.onclick=()=>{S.forecast=b.dataset.w;toast('Прогноз записан: '+weather[S.forecast][0]+'.');close()});ui.layer.querySelector('[data-close]').onclick=close}
function journal(){let tasks=taskPool.map(t=>{let seen=S.appearedTasks.includes(t.id),done=S.completedTasks.includes(t.id);return'<div class="journal-row '+(seen?'':'unknown')+'">'+(done?'✓ ':'')+(seen?t.requester+' — '+t.text:'???')+'</div>'}).join(''),body=npcs.map(n=>'<h3>'+n.name+' · '+n.job+'</h3>'+rules.filter(r=>r.npc===n.id).map(r=>{let loops=S.journal[r.id]?.loops||[],known=loops.length>=2,clue=S.taskHints[r.id];return'<div class="journal-row '+(known?'':'unknown')+'">'+(known?r.text:clue?'??? — '+clue:'???')+(loops.length?' ('+Math.min(2,loops.length)+'/2)':'')+'</div>'}).join('')).join(''),conflictSteps={'old-friends':['Ангус признался, что скучает по «Гадюкам».','Дуги согласился встретиться.'],'fish-buns':['Хэмиш согласился продавать с лодки.','Мораг заказала рыбу для пирога.'],'psalms-pipes':['Иэн признался, что волынка почти псалом.','Рэб согласился играть у кирка.']},conflictRows=conflicts.map(c=>{if(c.resolved)return'<div class="journal-row">✓ '+c.title+'</div>';let seen=c.id==='old-friends'?(S.storySeen[c.id]||[]):(S.conflictSeen[c.id]||[]);return'<div class="journal-row"><strong>'+c.title+'</strong>'+conflictSteps[c.id].map((line,i)=>'<div>'+(seen.includes(i+1)?(i+1)+'. '+line:(i+1)+'. ???')+'</div>').join('')+'</div>'}).join(''),storyRows=stories.map(st=>{if(storyResolved(st.id))return'<div class="journal-row">✓ '+st.title+'</div>';let seen=S.storySeen[st.id]||[];return'<div class="journal-row"><strong>'+st.title+'</strong>'+st.steps.map((line,i)=>'<div>'+(seen.includes(i+1)?(i+1)+'. '+line:(i+1)+'. ???')+'</div>').join('')+'</div>'}).join(''),observations=S.observations.length?S.observations.map(t=>'<div class="journal-row">'+t+'</div>').join(''):'<div class="journal-row">Пока нет наблюдений.</div>';open('<h2>Дневник наблюдений</h2><h3>Задания: '+S.completedTasks.length+'/10</h3>'+tasks+body+'<h3>Чужак</h3><div class="journal-row">Руперт Скуннерсби · лондонский делец. Не житель Глен-Дриха.</div><h3>Конфликты</h3>'+conflictRows+'<h3>Истории</h3>'+storyRows+'<h3>Финал</h3><div class="journal-row">Матчей сыграно: '+S.matchesPlayed+'. Лучший счёт: '+(S.bestResult?S.bestResult.vipers+' : '+S.bestResult.siller:'пока нет')+'</div><h3>Наблюдения</h3>'+observations+'<p class="close-hint">J или Esc · закрыть</p>')}
function summary(){if(S.task&&!S.taskDone)failTask();let actual=S.cond.afternoon,correct=S.forecast===actual,observations=[...S.seen].map(id=>rules.find(r=>r.id===id)?.text).filter(Boolean);open('<h2>День окончен</h2><div class="summary"><p>Утром — '+weather[S.cond.morning][0]+'. После полудня — '+weather[actual][0]+'.</p><p>'+(S.forecast&&S.forecast!=='none'?(correct?'Прогноз верен: ':'Прогноз ошибся: ')+weather[S.forecast][0]+' · '+weather[actual][0]:'Прогноз не сделан.')+'</p><p>Новых наблюдений: '+observations.length+'.</p><p>Задание: '+(S.task?S.task.requester+' — '+taskStatus()+'.':'нет задания.')+'</p></div><button id="again">Проснуться снова</button>');document.querySelector('#again').onclick=()=>{S.loop++;begin()};S.active=false}
function npcDoor(n){let loc=npcLoc(n.id);let closed={malcolm:'smithy',rory:'lodge',bridie:'croft'}[n.id];if(closed&&loc===closed)return buildings.find(b=>b.id===closed).door;if(n.id==='dougie'&&loc==='hut')return buildings.find(b=>b.id==='hut').door;if(n.id==='iain'&&loc==='kirk')return buildings.find(b=>b.id==='kirk').door;if(n.id==='hamish'&&loc==='boat')return locations.boat;let home=buildings.find(b=>b.id==='home');if(n.x>home.x+.3&&n.x<home.x+home.w-.3&&n.y>home.y+1.15&&n.y<home.y+home.h-.15)return{x:home.x+home.w/2,y:home.y+home.h+.35};return null}
function nearestInteractable(){let items=[];for(const n of npcs){let door=npcDoor(n);if(door){let d=dist(S.player,door);if(d<1.35)items.push({type:'knock',npc:n,pos:door,d})}else{let d=dist(S.player,n);if(d<1.35)items.push({type:'npc',npc:n,pos:n,d})}}if(angus.visible){let d=dist(S.player,angus);if(d<1.35)items.push({type:'angus',npc:angus,pos:angus,d})}if(rupert.visible){let d=dist(S.player,rupert);if(d<1.35)items.push({type:'rupert',npc:rupert,pos:rupert,d})}if(S.receiptAvailable&&!S.receiptHeld){let pos=S.receiptSpot,d=dist(S.player,pos);if(d<1.35)items.push({type:'receipt',pos,d})}for(const item of [{type:'desk',pos:{x:18.5,y:10.1},d:0},{type:'bed',pos:{x:8,y:8.5},d:0}]){if(item.type==='desk'&&(S.forecast!==null||S.time>=9))continue;item.d=dist(S.player,item.pos);if(item.d<1.35)items.push(item)}return items.sort((a,b)=>a.d-b.d)[0]||null}

function getLabelActor(){let target=nearestInteractable();if(target&&['npc','knock','angus','rupert'].includes(target.type))return target.npc;let options=npcs.filter(n=>!npcDoor(n)).concat(angus.visible?[angus]:[]).concat(rupert.visible?[rupert]:[]).map(n=>({n,d:dist(S.player,n)})).filter(o=>o.d<=3).sort((a,b)=>a.d-b.d);return options[0]?.n||null}
function interact(){let item=nearestInteractable();if(!item)return;if(item.type==='receipt'){pickUpReceipt();return}if(item.type==='rupert'){toast('Руперт Скуннерсби: «'+pick(rupert.lines)+'»',3600);return}if(item.type==='angus'){let p=storyProgress();if(!conflictResolved('old-friends')&&S.cond.event==='angus'&&S.time>=10&&S.time<13&&p.step===0&&dist(angus,locations.green)<1.35){p.step=1;markStoryStep('old-friends',1);queueNotice('Ангус: «Я скучаю по „Гадюкам“. Даже по нашим спорам из-за свистка.»',2300);queueNotice('Ангус: «Стыдно смотреть Дуги в глаза. Он заслужил объяснение.»',2300);queueNotice('История: Ангус скучает по команде',2600);return}toast('Ангус Стрэй: «'+pick(angus.lines)+'»',3600);return}if(item.type==='desk'){forecast();return}if(item.type==='bed'){open('<h2>Лечь спать?</h2><p>Закончить этот день и начать новую петлю?</p><button id="sleep-yes">Лечь спать</button> <button class="plain-button" id="sleep-no">Остаться</button>');document.querySelector('#sleep-yes').onclick=summary;document.querySelector('#sleep-no').onclick=close;return}let target=item.npc;if(target.id==='elspeth'&&S.receiptHeld&&S.cond.event==='rupert'&&S.time<17&&!storyResolved('bribed-referee')){let seen=S.storySeen['bribed-referee']||[];if(seen.includes(1)&&seen.includes(2)){if(S.moods.elspeth<50){if(!S.talked.has('elspeth')){S.talked.add('elspeth');mood('elspeth',5)}toast('Элспет: «Сегодня у меня нет сил затевать драку.»',3200);return}S.receiptHeld=false;storyProgress('bribed-referee').scoopAccepted=true;if(!S.talked.has('elspeth')){S.talked.add('elspeth');mood('elspeth',5)}toast('Элспет: «Доказательство есть. К пяти будет экстренный выпуск.»',3600);return}}if(target.id==='hamish'&&!conflictResolved('fish-buns')&&S.time<12&&S.moods.hamish>=66&&!storyProgress('fish-buns').hamishAgreed){storyProgress('fish-buns').hamishAgreed=true;markConflictStep('fish-buns',1);if(!S.talked.has('hamish')){S.talked.add('hamish');mood('hamish',5)}toast('Хэмиш: «Буду продавать с лодки. У печи мне всё равно не место.»',3600);return}if(target.id==='morag'&&!conflictResolved('fish-buns')&&S.time<15&&storyProgress('fish-buns').hamishAgreed&&S.moods.morag>=50){markConflictStep('fish-buns',2);if(!S.talked.has('morag')){S.talked.add('morag');mood('morag',5)}resolveConflict('fish-buns');toast('Мораг: «Закажу у него пикшу. Пирог сам себя не испечёт.» Конфликт разрешён.',3800);return}if(target.id==='morag'&&!conflictResolved('fish-buns')){if(!S.talked.has('morag')){S.talked.add('morag');mood('morag',5)}toast('Мораг: «Хэмиш торгует рыбой у самой двери пекарни. Скоро булки будут пахнуть причалом.»',3600);return}if(target.id==='iain'&&!conflictResolved('psalms-pipes')&&S.time>12&&S.b1Happened&&!storyProgress('psalms-pipes').iainAgreed){storyProgress('psalms-pipes').iainAgreed=true;markConflictStep('psalms-pipes',1);if(!S.talked.has('iain')){S.talked.add('iain');mood('iain',5)}toast('Иэн: «Волынка Рэба — почти псалом. Почти.»',3600);return}if(target.id==='iain'&&!conflictResolved('psalms-pipes')&&S.time>=12){if(!S.talked.has('iain')){S.talked.add('iain');mood('iain',5)}toast('Иэн: «Рэб опять упражняется ровно во время полуденной молитвы.»',3600);return}if(target.id==='rab'&&!conflictResolved('psalms-pipes')&&storyProgress('psalms-pipes').iainAgreed&&S.moods.rab>=66){markConflictStep('psalms-pipes',2);if(!S.talked.has('rab')){S.talked.add('rab');mood('rab',5)}resolveConflict('psalms-pipes');toast('Рэб: «У дверей кирка, в три. Почти псалом — я запомнил.» Конфликт разрешён.',3800);return}if(item.type==='knock'&&target.id==='dougie'&&S.cond.event==='angus'&&!conflictResolved('old-friends')&&storyProgress().step>=1&&S.time>=10&&S.time<15&&npcLoc('dougie')==='hut'){if(!S.talked.has(target.id)){S.talked.add(target.id);mood('dougie',5)}if(S.moods.dougie>=40){let p=storyProgress();p.step=2;p.agreed=true;markStoryStep('old-friends',2);queueNotice('Дуги: «В час буду в пабе. Ангусу давно пора сказать это мне в лицо.»',2300);queueNotice('История: Дуги согласился поговорить',2600)}else{queueNotice('Дуги: «Убирайся. Даже дверь устала меня слушать.»',2200);queueNotice('Дуги сейчас не в духе. Может, поднять ему настроение?',3200)}return}let moodval=S.moods[target.id],type=moodval>=66?'happy':moodval<34?'sad':'neutral',weatherIndex=Object.keys(weather).indexOf(S.time<12?S.cond.morning:S.cond.afternoon),lines=target.lines[type],activeHints=Object.entries(target.hints).filter(([id])=>rules.find(r=>r.id===id)?.when(S)).flatMap(([,hints])=>hints),useHint=moodval>50&&activeHints.length>0&&Math.random()<.5,line=useHint?pick(activeHints):lines[(weatherIndex+Math.floor(Math.random()*lines.length))%lines.length];toast((item.type==='knock'?'Стук в дверь. ':'')+target.name+': «'+line+'»',3600);if(!S.talked.has(target.id)){S.talked.add(target.id);mood(target.id,5)}}

function updatePrompt(){let el=document.querySelector('#prompt'),item=nearestInteractable();if(!item){el.classList.add('hidden');return}let label=item.type==='bed'?'E — лечь спать (закончить день)':item.type==='desk'?'E — написать прогноз':item.type==='receipt'?'E — поднять квитанцию':item.type==='knock'?'E — постучать к '+item.npc.name:'E — поговорить с '+item.npc.name;el.textContent=label;el.classList.remove('hidden');let shell=document.querySelector('#game-shell').getBoundingClientRect(),bounds=canvas.getBoundingClientRect(),sx=bounds.left-shell.left+(item.pos.x*16-S.cam.x)*3*bounds.width/960,sy=bounds.top-shell.top+(item.pos.y*16-S.cam.y)*3*bounds.height/720;el.style.left=Math.max(el.offsetWidth/2+6,Math.min(shell.width-el.offsetWidth/2-6,sx))+'px';el.style.top=Math.max(12,sy-28)+'px'}
let audioContext=null,soundEnabled=true;function initAudio(){if(!audioContext){let C=window.AudioContext||window.webkitAudioContext;if(C)audioContext=new C()}if(audioContext?.state==='suspended')audioContext.resume()}
function tone(freq,duration,type='sine',delay=0,volume=.035){if(!soundEnabled)return;initAudio();if(!audioContext)return;let now=audioContext.currentTime+delay,o=audioContext.createOscillator(),g=audioContext.createGain();o.type=type;o.frequency.setValueAtTime(freq,now);g.gain.setValueAtTime(volume,now);g.gain.exponentialRampToValueAtTime(.001,now+duration);o.connect(g);g.connect(audioContext.destination);o.start(now);o.stop(now+duration)}
function playWhistle(){tone(920,.12,'square',0,.025);tone(1120,.12,'square',.16,.025)}function playGoalChime(){tone(560,.12,'sine',0,.04);tone(820,.18,'sine',.11,.035)}function playGoalThud(){tone(92,.16,'sine',0,.065)}function playClick(){tone(640,.025,'square',0,.012)}
