const keys=new Set();window.addEventListener('keydown',e=>{let k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright','e','j',' ','m'].includes(k))e.preventDefault();if(k==='m'){toggleSound();return}if(S.matchMode){if(k==='escape')return;if(k===' '||k==='spacebar')keys.add('Space');else keys.add(e.code);return}if(!S.active){if(k==='escape'||k==='j'){if(ui.layer.classList.contains('team-screen')||S.endingActive)return;if(!ui.title.classList.contains('hidden'))returnToTitle();else close()}return}if(k==='e'){interact();return}if(k==='j'){journal();return}keys.add(e.code)});window.addEventListener('keyup',e=>{keys.delete(e.code);if(e.key===' ')keys.delete('Space')});window.addEventListener('blur',()=>keys.clear());
function onPier(x,y){return x>=31&&x<38&&y>=20&&y<=21}function water(x,y){return!onPier(x,y)&&(x>34.1&&y>9.4||x>29.5&&y>23.3||x>33&&y>20.2)}
function walkable(x,y,actor='player'){if(x<.5||y<.5||x>39.5||y>29.5||water(x,y))return false;for(const b of buildings){let inside=x>=b.x-.25&&x<=b.x+b.w+.25&&y>=b.y-.25&&y<=b.y+b.h+.25;if(!inside)continue;if(actor==='player'&&['home','kirk','hut','smithy','lodge','croft'].includes(b.id))return false;let floor=x>b.x+.35&&x<b.x+b.w-.35&&y>b.y+1.15&&y<b.y+b.h-.15,door=Math.abs(x-(b.door?.x??(b.x+b.w/2)))<.65&&y>=b.y+b.h-.15&&y<=b.y+b.h+.5;if(!floor&&!door)return false}return true}
function gridPoint(index){return{x:.5+(index%80)*.5,y:.5+Math.floor(index/80)*.5}}
function nearestGrid(x,y,actor){let best=-1,bestD=Infinity;for(let i=0;i<4800;i++){let p=gridPoint(i);if(!walkable(p.x,p.y,actor))continue;let d=(p.x-x)**2+(p.y-y)**2;if(d<bestD){best=i;bestD=d}}return best}
function nearestWalkable(x,y,actor='player'){let i=nearestGrid(x,y,actor);return i<0?{x:8.5,y:9}:gridPoint(i)}
function findGridPath(start,target,actor='npc'){let from=nearestGrid(start.x,start.y,actor),to=nearestGrid(target.x,target.y,actor);if(from<0||to<0)return[];let parent=new Int32Array(4800);parent.fill(-2);parent[from]=-1;let queue=new Int32Array(4800),head=0,tail=0;queue[tail++]=from;const steps=[[-1,0],[1,0],[0,-1],[0,1]];while(head<tail&&parent[to]===-2){let at=queue[head++],x=at%80,y=Math.floor(at/80);for(const [dx,dy] of steps){let nx=x+dx,ny=y+dy;if(nx<0||nx>=80||ny<0||ny>=60)continue;let next=ny*80+nx,p=gridPoint(next);if(parent[next]!==-2||!walkable(p.x,p.y,actor))continue;parent[next]=at;queue[tail++]=next}}if(parent[to]===-2)return[];let route=[];for(let at=to;at!==-1;at=parent[at])route.push(gridPoint(at));route.reverse();if(walkable(target.x,target.y,actor)&&dist(route[route.length-1],target)>.02)route.push({x:target.x,y:target.y});return route}
function movePlayer(dt){S.player.moving=false;if(!walkable(S.player.x,S.player.y))Object.assign(S.player,nearestWalkable(S.player.x,S.player.y));let x=(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0),y=(keys.has('KeyS')||keys.has('ArrowDown')?1:0)-(keys.has('KeyW')||keys.has('ArrowUp')?1:0);if(!x&&!y){S.player.animTime=0;return}let d=Math.hypot(x,y),step=Math.max(dt,.001)*2.65;x=x/d*step;y=y/d*step;faceActor(S.player,x,y);let beforeX=S.player.x,beforeY=S.player.y;attempt(S.player.x+x,S.player.y);attempt(S.player.x,S.player.y+y);S.player.moving=S.player.x!==beforeX||S.player.y!==beforeY;S.player.animTime=S.player.moving?(S.player.animTime||0)+dt:0}
function attempt(x,y){if(walkable(x,y)){S.player.x=x;S.player.y=y}}
function checkOldFriendsScene(){let p=storyProgress();if(p.sceneStarted||p.step<2||conflictResolved('old-friends')||S.cond?.event!=='angus'||S.time<13||S.time>=15)return;let dougie=npcs.find(n=>n.id==='dougie');if(npcLoc('dougie')==='pub'&&inPub(dougie)&&inPub(angus)&&inPub(S.player)){p.sceneStarted=true;S.active=false;const finish=()=>{p.step=3;markStoryStep('old-friends',3);resolveConflict('old-friends');S.active=true};queueNotice('Ангус: «Дуги, я скучал по «Гадюкам». Даже по вашим вечным спорам о свистке.»',2200);queueNotice('Дуги: «А я думал, ты ушёл, потому что у Силлерберна трава ровнее.»',2200);queueNotice('Ангус: «Трава ровнее. Люди — не обязательно. Прости, что не вернулся раньше.»',2200);queueNotice('Дуги: «Не опоздал. Тренировка завтра. Опоздаешь — скажу, что так и задумано.»',2200);queueNotice('Конфликт разрешён: Старые друзья',2600,false,finish)}}

function finalStrength(){let present=S.finalArrivals.map(id=>npcs.find(n=>n.id===id)).filter(Boolean),conflictPoints=conflicts.reduce((sum,c)=>sum+(c.resolved?FINAL_CONFIG.resolvedConflict:FINAL_CONFIG.unresolvedConflict),0),weatherPoints=S.cond.afternoon==='sun'?FINAL_CONFIG.sunPenalty:(['rain','fog'].includes(S.cond.afternoon)&&S.forecast==='sun'?FINAL_CONFIG.rainForecastBonus:0),refereePoints=S.refereeFair?0:FINAL_CONFIG.bribedReferee,vipers=present.reduce((sum,n)=>sum+(S.moods[n.id]||0),0)+conflictPoints+weatherPoints+refereePoints,ratio=Math.max(.3,Math.min(1.4,vipers/FINAL_CONFIG.sillerburn));return{present,vipers,ratio,conflictPoints,weatherPoints,refereePoints}}
