function showTeamSheet(){const calc=finalStrength(),names=calc.present.map(n=>n.name),rows=npcs.map(n=>{let arrived=calc.present.includes(n);return '<div class="team-row">'+teamSheetPortrait(n.id)+'<span>'+n.name+'</span><b>'+Math.round(S.moods[n.id]||0)+'</b><em class="'+(arrived?'arrived':'absent')+'">'+(arrived?'на поле':'не пришёл')+'</em></div>'}).join(''),conf=conflicts.map(c=>'<div class="modifier">'+c.title+' <b>'+(c.resolved?'разрешён':'не разрешён')+'</b></div>').join(''),weatherMod=S.cond.afternoon==='sun'?'−30 · солнце':(['rain','fog'].includes(S.cond.afternoon)&&S.forecast==='sun'?' +60 · дождь/туман при прогнозе солнца':'0 · погода'),ratio=calc.ratio,verdict=ratio<.62?'Шансов почти нет':ratio<.95?'Тяжело, но можно':'Мы сильнее';ui.layer.classList.add('team-screen');open('<h2>Гадюки Глен-Дриха — Силлерберн</h2><div class="team-list">'+rows+'</div><div class="modifiers"><div class="modifier">'+(S.refereeFair?'Судья честный':'Судья подкуплен')+'</div><div class="modifier">Погода: '+weather[S.cond.afternoon][0]+' · прогноз: '+(S.forecast&&S.forecast!=='none'?weather[S.forecast][0]:'нет')+' ('+weatherMod+')</div>'+conf+'</div><div class="strength"><div><span>Гадюки</span><b>'+Math.round(calc.vipers)+'</b></div><div class="bar"><i style="width:'+Math.max(4,Math.min(100,ratio/1.4*100))+'%"></i></div><div><span>Силлерберн</span><b>900</b></div><div class="bar enemy"><i style="width:72%"></i></div><p>'+verdict+'</p></div><button id="final-play">На поле</button>');drawTeamPortraits();document.querySelector('#final-play').onclick=()=>{ui.layer.classList.remove('team-screen');startMatch()}}
function startMatch(){const calc=finalStrength(),available=calc.present.slice().sort((a,b)=>(S.moods[b.id]||0)-(S.moods[a.id]||0));let selected=available.slice(0,5),hamish=available.find(n=>n.id==='hamish');if(hamish&&!selected.includes(hamish)){selected=selected.slice(0,4);selected.push(hamish)}selected.sort((a,b)=>a.id==='hamish'?-1:b.id==='hamish'?1:(S.moods[b.id]||0)-(S.moods[a.id]||0));let teammates=selected.map((n,i)=>makeMatchPlayer(n.id,'viper',i+1,n.id==='hamish'));let opponents=SILLERBURN_ROSTER.map((d,i)=>makeMatchPlayer(d,'siller',i,d.keeper));let hero=makeMatchPlayer('oliver','viper',0,false);hero.x=88;hero.y=120;hero.isOliver=true;S.match={elapsed:0,remaining:FINAL_CONFIG.matchSeconds,ratio:calc.ratio,score:{vipers:0,siller:0},oliverGoals:0,players:[hero,...teammates,...opponents],ball:{x:160,y:120,vx:0,vy:0,owner:null},ownerSince:0,lastShot:0,ballStillFor:0,lastBallX:160,lastBallY:120,lastAIShot:{viper:-Infinity,siller:-Infinity},goalFreezeRemaining:0,kickoffSide:null,countdown:3,countdownElapsed:0,started:false,popup:'',popupUntil:0};S.matchMode=true;S.active=false;S.matchesPlayed++;keys.clear();ui.hud.classList.add('hidden');ui.layer.classList.add('hidden')}
