separateMatchPlayers(m.players);if(ball.owner){let current=m.players.find(p=>p.id===ball.owner);if(current){ball.x=Math.max(18,Math.min(302,current.x+(current.side==='viper'?7:-7)));ball.y=Math.max(44,Math.min(188,current.y+2))}}
if(Math.hypot(ball.x-oldX,ball.y-oldY)<.18)m.ballStillFor+=dt;else m.ballStillFor=0;if(m.ballStillFor>=3){ball.x=160;ball.y=120;ball.vx=ball.vy=0;ball.owner=null;m.ballStillFor=0;m.ownerSince=m.elapsed;ball.ignoreOwnerUntil=m.elapsed+.25}
