function matchSkill(p){let m=S.match,sideFactor=p.side==='viper'?m.ratio:1/Math.max(.3,m.ratio);return Math.max(FINAL_CONFIG.skillMinimum,Math.min(FINAL_CONFIG.skillMaximum,sideFactor*(FINAL_CONFIG.skillMoodBase+p.mood/FINAL_CONFIG.skillMoodDivisor)))}
function scoreMatchGoal(m,side){if(side==='vipers')m.score.vipers++;else m.score.siller++;if(m.ball.wasShot&&m.ball.shooterId===m.players.find(p=>p.isOliver)?.id)m.oliverGoals++;if(side==='vipers')playGoalChime();else playGoalThud();let scorer=m.ball.shooterName||'Игрок';m.popup='ГОЛ! '+scorer;m.popupUntil=m.elapsed+FINAL_CONFIG.goalFreezeSeconds;resetMatchBall(m,side);m.goalFreezeRemaining=FINAL_CONFIG.goalFreezeSeconds}
function shootMatch(p,direction){let m=S.match,ball=m.ball,targetX=direction>0?302:18,keeper=m.players.find(o=>o.side===(direction>0?'siller':'viper')&&o.keeper),attackFactor=p.side==='viper'?m.ratio:1/Math.max(.3,m.ratio);let accuracy=Math.max(.42,Math.min(1,attackFactor*(.68+p.mood/260)));if(p.isOliver)accuracy=Math.min(1,accuracy*FINAL_CONFIG.oliverAccuracyBonus);let targetY=120+(Math.random()-.5)*(23/accuracy),speed=150*accuracy,flight=Math.abs(targetX-p.x)/speed,distance=Math.abs(targetX-p.x),distanceFactor=Math.max(0,Math.min(1,distance/FINAL_CONFIG.keeperDistanceForMax)),shooterSkill=matchSkill(p),ownSkill=matchSkill(keeper),saveChance=FINAL_CONFIG.keeperSaveBase+FINAL_CONFIG.keeperSkillWeight*(ownSkill-shooterSkill)+FINAL_CONFIG.keeperDistanceWeight*distanceFactor;if(p.isOliver)saveChance-=FINAL_CONFIG.oliverKeeperPenalty;saveChance=Math.max(FINAL_CONFIG.keeperSaveMin,Math.min(FINAL_CONFIG.keeperSaveMax,saveChance));ball.owner=null;ball.ignoreOwnerUntil=m.elapsed+.4;ball.x=p.x+direction*8;ball.y=p.y;ball.shooterName=p.name;ball.shooterId=p.id;ball.wasShot=true;ball.vx=direction*speed;ball.vy=(targetY-p.y)/(flight||1);let keeperY=keeper.y+(targetX-keeper.x)/ball.vx*ball.vy;if(Math.abs(keeperY-keeper.y)<17&&Math.random()<saveChance){ball.owner=keeper.id;m.ownerSince=m.elapsed;ball.x=keeper.x+(direction>0?-4:4);ball.y=keeper.y;ball.vx=ball.vy=0}}
function resetMatchBall(m,scoringSide){m.ball={x:160,y:120,vx:0,vy:0,owner:null,ignoreOwnerUntil:m.elapsed+.25};m.ownerSince=m.elapsed;m.ballStillFor=0;let conceded=scoringSide==='vipers'?'siller':'viper';m.kickoffSide=conceded;m.players.forEach(p=>{if(p.isOliver){p.x=scoringSide==='vipers'?92:160;p.y=120}else if(p.side==='viper'){p.x=p.homeX;p.y=p.homeY}else{p.x=p.homeX;p.y=p.homeY}clampMatchPlayer(p)});let kicker=conceded==='viper'?m.players.find(p=>p.isOliver):m.players.find(p=>p.id==='sb-angus');if(kicker){kicker.x=160;kicker.y=120;m.ball.owner=kicker.id;m.ball.ignoreOwnerUntil=0;m.ownerSince=m.elapsed}}
