function finishMatch(){let m=S.match,won=m.score.vipers>m.score.siller&&m.oliverGoals>0;playWhistle();S.finalStoryResolved=true;let finalStory=stories.find(x=>x.id==='shinty-final');if(finalStory)finalStory.resolved=true;S.finalScore={...m.score};S.matchMode=false;S.match=null;ui.hud.classList.remove('hidden');if(!S.bestResult||S.finalScore.vipers>S.bestResult.vipers||(S.finalScore.vipers===S.bestResult.vipers&&S.finalScore.siller<S.bestResult.siller))S.bestResult={...S.finalScore};save();if(won)runEnding(0);else{let absent=npcs.filter(n=>!S.finalArrivals.includes(n.id)),hint=m.score.vipers>m.score.siller&&m.oliverGoals===0?'Оливер так и не забил. Решающий гол должен быть его.':absent.length?'Не пришли: '+absent.slice(0,2).map(n=>n.name.split(' ')[0]).join(', '):!S.refereeFair?'Судья всё ещё подкуплен':conflicts.find(c=>!c.resolved)?.title||'Прогноз подвёл';open('<h2>Финал проигран</h2><p>Счёт: '+S.finalScore.vipers+' : '+S.finalScore.siller+'</p><p>'+hint+'</p><button id="defeat-next">К итогу дня</button>');document.querySelector('#defeat-next').onclick=()=>{ui.layer.classList.remove('team-screen');summary()}}}
