function update(dt){if(S.matchMode){updateMatch(dt);return}if(!S.active)return;S.elapsed+=dt;S.time=6+S.elapsed/50;if(S.time>=15.5&&!S.finalGathered)beginFinalGather();checkFirstLoopHints();if(S.time>=16&&!S.finalHandled){S.finalHandled=true;handleFinalKickoff()} if(S.time>=9&&S.forecast===null)S.forecast='none';if(S.time>=12&&!S.weatherDone){S.weatherDone=true;let ok=S.forecast===S.cond.afternoon;npcs.forEach(n=>mood(n.id,ok?10:-10));toast(ok?'Прогноз сбылся. Настроение жителей +10.':'Прогноз не сбылся. Настроение жителей −10.',3200)}if(S.time>=7&&S.time<7.04&&!S.ritual){S.ritual=true;let text={emerged:'Натэр вышел из норы: жители ждут ясного дня.',stayed:'Натэр остался в норе: говорят, день будет дождливым.',peeked:'Натэр выглянул и спрятался: туман сулит перемены.'}[S.cond.sign];toast('Утренний обряд · '+text,4300)}checkRupertStory();if(S.time>=18){summary();return}movePlayer(dt);moveNPCs(dt);moveAngus(dt);moveRupert(dt);updateSheep(dt);checkOldFriendsScene();if(!S.active)return;checkRupertStory();discover();applyRules();applyConflictEffects();checkTask();S.cam.x=Math.max(WORLD.minX*16,Math.min(WORLD.maxX*16-320,S.player.x*16-160));S.cam.y=Math.max(WORLD.minY*16,Math.min(WORLD.maxY*16-240,S.player.y*16-120));document.querySelector('#clock').textContent=clock();document.querySelector('#loop-label').textContent='Петля '+S.loop;document.querySelector('#weather-icon').textContent=weather[S.time<12?S.cond.morning:S.cond.afternoon][1];updatePrompt();if(performance.now()>S.toastUntil)ui.toast.classList.add('hidden')}
function checkFirstLoopHints(){if(S.loop!==1)return;for(const h of [{id:'6:05',at:6+5/60,text:'Сначала — на обряд на площади в 7:00. Посмотри, что сделает гадюка.'},{id:'7:35',at:7+35/60,text:'Зайди в редакцию газеты до 9:00 и выбери прогноз.'},{id:'9:05',at:9+5/60,text:'Ходи за жителями. Их привычки попадают в дневник (J).'},{id:'15:00',at:15,text:'В 16:00 на поле для шинти — финал. Будь там.'}])if(S.time>=h.at&&!S.hintsSeen[h.id]){S.hintsSeen[h.id]=true;save();queueNotice(h.text,3600)}}
