function proceduralBuilding(b){let x=b.x*16,y=b.y*16,w=b.w*16,h=b.h*16;rect(x-2,y+h-5,w+4,7,P.ink);rect(x,y,w,h,P.stone);rect(x+3,y+18,w-6,h-20,P.light);rect(x+3,y,w-6,18,b.roof);for(let i=4;i<w-5;i+=9)rect(x+i,y+5,5,2,P.stone);rect(x-2,y-2,w+4,5,P.ink);rect(x,y-1,w,3,b.roof);if(b.id==='pub'){rect(x+8,y+21,18,12,P.path);rect(x+13,y+24,8,7,P.red);rect(x+5,y+30,14,10,P.ink);rect(x+6,y+31,12,8,P.red);rect(x+8,y+31,2,8,P.ink);rect(x+12,y+31,2,8,P.ink);rect(x+6,y+34,12,1,P.ink);rect(x+7,y+32,4,3,P.mist);glow(x+4,y+20);glow(x+53,y+20);rect(x+31,y+30,12,17,P.ink);rect(x+33,y+32,8,15,P.path)}else{glow(x+11,y+21);glow(x+w-23,y+21);rect(x+w/2-6,y+h-19,12,19,P.ink);rect(x+w/2-4,y+h-17,8,17,P.path)}if(b.id==='office'){rect(x+22,y+22,23,8,P.ink);rect(x+24,y+23,19,5,P.gold);rect(x+25,y+24,15,1,P.ink)}}
