function weatherFx(){let w=S.time<12?S.cond.morning:S.cond.afternoon,now=performance.now();if(w==='rain')for(let i=0;i<75;i++){let x=(hash(i,Math.floor(now/130))*320/4294967295+(now/14+i*31)%320)%320,y=(hash(i,Math.floor(now/170)+5)*240/4294967295+(now/7+i*17)%240)%240;rect(x,y,1,4,P.water)}if(w==='fog'){ctx.globalAlpha=.22;rect(0,0,320,240,P.mist);ctx.globalAlpha=.45;for(let i=0;i<5;i++)rect((now/50+i*83)%380-40,30+i*39,65,5,P.light);ctx.globalAlpha=1}if(w==='sun'){ctx.globalAlpha=.08;rect(0,0,320,240,P.gold);ctx.globalAlpha=1}if(w==='wind')for(let i=0;i<35;i++)rect((i*47+(now/12)%320)%320,(i*31)%240,2,1,P.moss)}
